export type Schedule = { hour: number; minute: number };

export function nextRun(schedule: Schedule): Date {
  const now = new Date();
  const nextRunTime = new Date(now);
  nextRunTime.setHours(schedule.hour, schedule.minute, 0, 0);

  if (nextRunTime <= now) {
    nextRunTime.setDate(nextRunTime.getDate() + 1);
  }

  return nextRunTime;
}

